  'दशमेश दूसरे भाव में होने से आपका करियर वित्त, भोजन, वाणी या पारिवारिक व्यापार से जुड़ा है। बैंकिंग, शिक्षण, बिक्री या संसाधन प्रबंधन से जुड़ा काम आपको अच्छा फल देता है।',
  'दशमेश तीसरे भाव में होने से संवाद और कौशल आपके करियर को आगे बढ़ाते हैं। लेखन, मीडिया, मार्केटिंग, यात्रा से जुड़ा काम या तकनीकी व्यवसाय उपयुक्त हैं, और साहस आपको ऊपर उठाता है।',
  'दशमेश चौथे भाव में होने से आपका काम भूमि, संपत्ति, वाहन, शिक्षा या घर से चलने वाले व्यापार से जुड़ा हो सकता है। घर के निकट स्थिर कार्यस्थल आपके लिए अच्छा है।',
  'दशमेश पाँचवें भाव में होने से बुद्धि और रचनात्मकता आपके करियर को लाभ देती हैं। शिक्षण, परामर्श, वित्त, मनोरंजन या बच्चों से जुड़ा काम इसके अनुसार शुभ है।',
  'दशमेश छठे भाव में होने से आप सेवा, स्वास्थ्य, कानून, प्रतिस्पर्धा और समस्या-समाधान वाले कामों में अच्छा करते हैं। कठिन परिश्रम और कठिन परिस्थितियों को संभालकर आप सफल होते हैं।',
  'दशमेश सातवें भाव में होने से आपका करियर साझेदारी, ग्राहकों और सार्वजनिक व्यवहार से बढ़ता है। व्यापार, परामर्श, वाणिज्य और यात्रा से जुड़ा काम शुभ है।',
  'दशमेश आठवें भाव में होने से करियर में अचानक परिवर्तन आ सकते हैं। शोध, बीमा, जाँच, कराधान या गूढ़ विषय आपके लिए उपयुक्त हैं, और स्थिरता के लिए धैर्य आवश्यक है।',
  'दशमेश नौवें भाव में होने से आपके करियर पर भाग्य और अच्छे मार्गदर्शकों का आशीर्वाद रहता है। शिक्षण, कानून, धर्म, प्रकाशन या विदेश में काम आपको सम्मान और प्रगति दे सकता है।',
  'दशमेश अपने ही दसवें भाव में होने से आपका करियर मज़बूत और प्रमुख रहता है। आप अधिकार वाले पदों तक पहुँच सकते हैं, और आपका काम आपको सार्वजनिक पहचान दिलाता है।',
  'दशमेश ग्यारहवें भाव में होने से करियर से निरंतर आय और लाभ मिलता है। बड़े संगठन, नेटवर्किंग और सामूहिक परियोजनाएँ आपकी व्यावसायिक सफलता में सहायक हैं।',
  'दशमेश बारहवें भाव में होने से आपका काम विदेश, अस्पताल, दान-संस्थाओं या पर्दे के पीछे की भूमिकाओं से जुड़ा हो सकता है। प्रयास को बचत में बदलने के लिए सावधान योजना आवश्यक है।',
 ],
 'business' => [
  'सप्तमेश पहले भाव में होने से आप अपनी शर्तों पर व्यापार चला सकते हैं, और साझेदार आसानी से मिलते हैं। आपकी व्यक्तिगत छवि आपकी सबसे बड़ी व्यावसायिक पूँजी है।',
  'सप्तमेश दूसरे भाव में होने से परिवार के साथ या वित्त, भोजन और वस्तुओं के व्यापार में काम इसके अनुसार शुभ है। साझेदारी से आपका धन बढ़ सकता है।',
  'सप्तमेश तीसरे भाव में होने से संचार, मीडिया, परिवहन, खुदरा या निकट दूरी के व्यापार आपके लिए उपयुक्त हैं। भाई-बहन या निकट परिचित साझेदार बन सकते हैं।',
  'सप्तमेश चौथे भाव में होने से संपत्ति, निर्माण, वाहन, कृषि या घरेलू वस्तुओं का व्यापार शुभ है। घर के निकट पारिवारिक दुकान या कार्यालय अच्छा चल सकता है।',
  'सप्तमेश पाँचवें भाव में होने से सट्टा, रचनात्मक या शिक्षा से जुड़ा व्यापार आपको आकर्षित करता है। निवेश से पहले सोच-विचार करें और साझेदारों के साथ स्पष्ट समझौता रखें।',
  'सप्तमेश छठे भाव में होने से व्यावसायिक साझेदारी में विवाद हो सकते हैं, इसलिए लिखित समझौते महत्वपूर्ण हैं। सावधानी से सेवा व्यवसाय, क्लिनिक या कानूनी कार्य सफल हो सकते हैं।',
  'सप्तमेश अपने ही सातवें भाव में होने से व्यापार और साझेदारी को प्रबल समर्थन मिलता है। वाणिज्य, जनता से व्यवहार और संयुक्त उद्यम अच्छे परिणाम दे सकते हैं।',
  'सप्तमेश आठवें भाव में होने से व्यापार में अचानक लाभ और हानि हो सकती है। बीमा, शोध या संयुक्त वित्त आपके लिए उपयुक्त हैं, पर बिना जाँच-परख के जोखिम भरी साझेदारी से बचें।',
  'सप्तमेश नौवें भाव में होने से विदेश व्यापार, शिक्षा, प्रकाशन या धर्म से जुड़ा व्यापार शुभ है। सौभाग्य आपकी साझेदारियों को सहारा देता है।',
  'सप्तमेश दसवें भाव में होने से व्यापार और करियर अच्छी तरह जुड़ते हैं। आप एक प्रतिष्ठित उद्यम बना सकते हैं, और साझेदार आपकी प्रतिष्ठा बढ़ाते हैं।',
  'सप्तमेश ग्यारहवें भाव में होने से व्यापार से निरंतर लाभ और उपयोगी संपर्क मिलते हैं। बड़े नेटवर्क, निर्यात या सामूहिक उद्यम इसके अनुसार शुभ हैं।',
  'सप्तमेश बारहवें भाव में होने से आयात-निर्यात और विदेशी व्यापार उपयुक्त हैं, पर खर्चों पर कड़ी नज़र रखें। साझेदार सावधानी से चुनें और हिसाब-किताब पारदर्शी रखें।',
 ],
 'health' => [
  'आपकी शारीरिक बनावट मज़बूत और ऊर्जावान है, पर सिर, आँखों और रक्तचाप का ध्यान रखें। जल्दबाज़ी और अधिक गर्मी से बचें, तथा दिनचर्या में पर्याप्त विश्राम रखें।',
  'आपमें प्रायः अच्छी सहनशक्ति होती है, पर गला, गर्दन और थायरॉइड संवेदनशील अंग हैं। भोजन में संयम और नियमित व्यायाम आपका वज़न और ऊर्जा संतुलित रखते हैं।',
  'आपका स्वास्थ्य नसों, फेफड़ों और कंधों से जुड़ा है। अधिक मानसिक काम और अनियमित नींद आपको थका सकती है, इसलिए प्राणायाम और शांत दिनचर्या लाभदायक है।',
  'आपकी छाती, पेट और पाचन संवेदनशील हैं, और भावनाएँ आपके स्वास्थ्य को प्रभावित करती हैं। ताज़ा घर का बना भोजन और भावनात्मक शांति आपके लिए सबसे अच्छी औषधि है।',
  'आपमें अच्छी जीवनशक्ति है, पर हृदय, रीढ़ और पीठ पर ध्यान दें। संतुलित सक्रियता, अधिक तनाव से बचाव और नियमित जाँच आपको स्वस्थ रखती है।',
  'आपका पाचन और आँतें चिंता के प्रति संवेदनशील हैं। स्वच्छ, सादा भोजन, नियमित भोजन-समय और अधिक सोच-विचार पर नियंत्रण आपके स्वास्थ्य में सहायक है।',
  'गुर्दे, कमर का निचला भाग और त्वचा आपके लिए संवेदनशील हैं। पर्याप्त पानी पीना, संतुलित जीवनशैली और अधिक मिठाई से परहेज़ इसके अनुसार सलाह दी जाती है।',
  'आपमें ठीक होने की प्रबल शक्ति है, पर प्रजनन और उत्सर्जन तंत्र का ध्यान रखें। तनाव को भीतर न रखें और नियमित स्वास्थ्य जाँच कराते रहें।',
  'कूल्हे, जाँघें और यकृत पर ध्यान दें, और अधिक खाना आपकी कमज़ोरी हो सकती है। बाहरी गतिविधि, पैदल चलना और संयमित आहार आपका स्वास्थ्य अच्छा रखते हैं।',
  'आपकी हड्डियों, जोड़ों, घुटनों और दाँतों पर विशेषकर उम्र के साथ ध्यान देना चाहिए। नियमित व्यायाम, कैल्शियम युक्त भोजन और ठंड में गर्माहट लाभदायक है।',
  'रक्त संचार, टखने और तंत्रिका तंत्र आपके लिए संवेदनशील हैं। नियमित चलना-फिरना, अच्छी नींद और अनियमित दिनचर्या से बचाव आपको स्वस्थ रखते हैं।',
  'पैर, रोग-प्रतिरोधक क्षमता और लसीका तंत्र का ध्यान रखें, और आप दवाओं के प्रति संवेदनशील हो सकते हैं। विश्राम, स्वच्छ जल, ध्यान और शांत वातावरण आपके स्वास्थ्य में सहायक हैं।',
 ],
 'hobbies' => [
  'तृतीयेश पहले भाव में होने से आपको खेल, साहसिक कार्य और वे गतिविधियाँ पसंद हैं जिनमें आप अपना कौशल दिखा सकें। आत्म-विकास और फिटनेस आपकी स्वाभाविक रुचियाँ हैं।',
  'तृतीयेश दूसरे भाव में होने से आपको संगीत, गायन, खाना बनाना और मूल्यवान वस्तुओं का संग्रह पसंद है। भोजन पर अच्छी बातचीत आपके आनंदों में से एक है।',
  'तृतीयेश अपने ही तीसरे भाव में होने से लेखन, यात्रा, फ़ोटोग्राफ़ी, खेल और हस्तकला में आपकी रुचि है। अपने हाथों से नए कौशल सीखना आपको अच्छा लगता है।',
  'तृतीयेश चौथे भाव में होने से आपको घर की सजावट, बागवानी, पढ़ना और परिवार के साथ समय बिताना पसंद है। घर पर आरामदायक शौक आपके लिए उपयुक्त हैं।',
  'तृतीयेश पाँचवें भाव में होने से रचनात्मक कलाएँ, खेल, नाटक और पढ़ाना आपको आकर्षित करते हैं। आपमें चंचलता है और आपको दूसरों का मनोरंजन करना अच्छा लगता है।',
  'तृतीयेश छठे भाव में होने से आपको प्रतिस्पर्धी खेल, फिटनेस, पहेलियाँ और सेवा के माध्यम से दूसरों की सहायता करना पसंद है। चुनौतीपूर्ण शौक आपको भाते हैं।',
  'तृतीयेश सातवें भाव में होने से आपको सामाजिक गतिविधियाँ, नृत्य, साथी के साथ यात्रा और नए लोगों से मिलना पसंद है। साझा शौक आपके संबंध मज़बूत करते हैं।',
  'तृतीयेश आठवें भाव में होने से रहस्य, शोध, ज्योतिष और गूढ़ विषय आपको मोहित करते हैं। जिस विषय में रुचि हो, उसकी गहराई में जाना आपको अच्छा लगता है।',
  'तृतीयेश नौवें भाव में होने से दर्शन, लंबी यात्राएँ, भाषाएँ और धार्मिक अध्ययन में आपकी रुचि है। तीर्थयात्रा और सांस्कृतिक यात्राएँ आपको आनंद देती हैं।',
  'तृतीयेश दसवें भाव में होने से आपके शौक प्रायः व्यावसायिक कौशल बन जाते हैं। आपको ऐसी गतिविधियाँ पसंद हैं जिनसे पहचान मिले, जैसे सार्वजनिक भाषण या आयोजन करना।',
  'तृतीयेश ग्यारहवें भाव में होने से आपको क्लब, सामूहिक गतिविधियाँ, सोशल मीडिया और मित्रों के साथ शौक पसंद हैं। लोगों से जुड़ना ही आपके लिए आनंद है।',
  'तृतीयेश बारहवें भाव में होने से ध्यान, संगीत, फ़िल्में, विदेश यात्रा और शांत रचनात्मक कार्य आपको आकर्षित करते हैं। एकांत के शौक आपको विश्राम देते हैं।',
 ],
 'love' => [
  'शुक्र मेष राशि में होने से आप उत्साह और स्पष्टता से प्रेम करते हैं, और आत्मविश्वासी, ऊर्जावान लोगों की ओर आकर्षित होते हैं। आप जल्दी प्रेम में पड़ते हैं, इसलिए धैर्य से संबंध परिपक्व होते हैं।',
  'शुक्र अपनी राशि वृषभ में होने से आप निष्ठावान, स्नेही और रसिक हैं। आप स्थिर और सुखद संबंध चाहते हैं, और देखभाल तथा उपहारों से प्रेम व्यक्त करते हैं।',
  'शुक्र मिथुन राशि में होने से आपको चंचल, बुद्धिमान साथी और जीवंत बातचीत पसंद है। विविधता आपको आकर्षित करती है, इसलिए साझा रुचियाँ आपके संबंधों को ताज़ा रखती हैं।',
  'शुक्र कर्क राशि में होने से आप कोमल, देखभाल करने वाले और समर्पित हैं। आप भावनात्मक सुरक्षा और स्नेहपूर्ण घरेलू जीवन चाहते हैं, और अपने प्रियजनों का पोषण करते हैं।',
  'शुक्र सिंह राशि में होने से आप स्नेही, उदार और रोमांटिक हैं। आपको प्रशंसा और बड़े भाव-प्रदर्शन पसंद हैं, और आप अपने साथी को निष्ठा और गर्व देते हैं।',
  'शुक्र कन्या राशि में होने से आप व्यावहारिक सहायता और बारीकियों पर ध्यान देकर प्रेम दिखाते हैं। भावनाएँ व्यक्त करने में आप संकोची हो सकते हैं, और कम आलोचना से प्रेम में अधिक सुख मिलता है।',
  'शुक्र अपनी राशि तुला में होने से आप आकर्षक, रोमांटिक और साझेदारी के प्रति समर्पित हैं। आप संबंधों में सामंजस्य, सुंदरता और न्याय चाहते हैं।',
  'शुक्र वृश्चिक राशि में होने से आपका प्रेम गहरा, तीव्र और निष्ठावान होता है। आप पूर्ण विश्वास चाहते हैं, और ईर्ष्या को खुली बातचीत से संभालना चाहिए।',
  'शुक्र धनु राशि में होने से आप ऐसा साथी चाहते हैं जो मित्र और साथ घूमने वाला भी हो। प्रेम में ईमानदारी, स्वतंत्रता और साझा आदर्श आपके लिए महत्वपूर्ण हैं।',
  'शुक्र मकर राशि में होने से आप प्रेम को गंभीरता से लेते हैं और लंबे समय के संबंध बनाते हैं। पहले आप संकोची लग सकते हैं, पर आप बहुत भरोसेमंद हैं।',
  'शुक्र कुंभ राशि में होने से आप प्रेम में मित्रता और स्वतंत्रता को महत्व देते हैं। आप अनोखे, बुद्धिमान लोगों की ओर आकर्षित होते हैं, और आपको निकटता के साथ स्वतंत्रता भी चाहिए।',
  'शुक्र अपनी उच्च राशि मीन में होने से आप रोमांटिक, निःस्वार्थ और अत्यंत करुणामय हैं। आप बिना शर्त प्रेम करते हैं, पर साथी को अत्यधिक आदर्श न बनाएँ।',
 ],
 'finance' => [
  'द्वितीयेश पहले भाव में होने से आप अपने प्रयास और व्यक्तित्व से धन कमाते हैं। आपमें धन आकर्षित करने की स्वाभाविक क्षमता है, पर अपने ऊपर खर्च संतुलित रखें।',
  'द्वितीयेश अपने ही दूसरे भाव में होने से पारिवारिक धन और बचत को अच्छा समर्थन मिलता है। निरंतर संचय, मधुर वाणी और आर्थिक समझदारी आपकी स्थिति मज़बूत करती है।',
  'द्वितीयेश तीसरे भाव में होने से आय संचार, कौशल, यात्रा और स्वयं के प्रयास से आती है। आर्थिक मामलों में भाई-बहन शामिल हो सकते हैं।',
  'द्वितीयेश चौथे भाव में होने से धन संपत्ति, वाहन, भूमि और माता पक्ष से जुड़ा है। अचल संपत्ति में निवेश आपके लिए इसके अनुसार शुभ है।',
  'द्वितीयेश पाँचवें भाव में होने से बुद्धि और निवेश से धन आता है। शिक्षा, परामर्श और सावधानीपूर्ण निवेश से धन बढ़ सकता है, पर जुए से बचें।',
  'द्वितीयेश छठे भाव में होने से ऋण और स्वास्थ्य या विवादों पर खर्च पर ध्यान देना चाहिए। आप सेवा से कमा सकते हैं, पर बिना सुरक्षा के पैसा उधार न दें।',
  'द्वितीयेश सातवें भाव में होने से साझेदारी, विवाह और व्यापार से धन बढ़ता है। आपका जीवनसाथी परिवार की समृद्धि में योगदान दे सकता है।',
  'द्वितीयेश आठवें भाव में होने से आर्थिक स्थिति में उतार-चढ़ाव, अचानक लाभ और खर्च हो सकते हैं। बीमा, विरासत और संयुक्त धन महत्वपूर्ण हैं, इसलिए आपात निधि रखें।',
  'द्वितीयेश नौवें भाव में होने से भाग्य आपकी आर्थिक स्थिति को सहारा देता है। धन पिता, गुरु, यात्रा या धार्मिक कार्य से आ सकता है, और समय के साथ बढ़ता है।',
  'द्वितीयेश दसवें भाव में होने से आपका करियर धन का मुख्य स्रोत है। व्यावसायिक सफलता और प्रतिष्ठा आपको निरंतर आय देती है।',
  'द्वितीयेश ग्यारहवें भाव में होने से आय और लाभ को प्रबल समर्थन मिलता है। आय के अनेक स्रोत और अच्छा नेटवर्क आपको धन बनाने में सहायता करते हैं।',
  'द्वितीयेश बारहवें भाव में होने से खर्च योजना से अधिक हो सकते हैं, विशेषकर यात्रा, दान या सुख-सुविधा पर। बजट बनाना और नियमित बचत आपके लिए आवश्यक है।',
 ],
 'education' => [
  'पंचमेश पहले भाव में होने से आपकी बुद्धि तीक्ष्ण और स्वतंत्र है। जब विषय में आपकी व्यक्तिगत रुचि हो तब आप सबसे अच्छा सीखते हैं, और स्वाध्याय से उत्कृष्टता पा सकते हैं।',
  'पंचमेश दूसरे भाव में होने से आपकी स्मरणशक्ति अच्छी है और भाषा, वित्त या वाणी से जुड़े विषयों में आपकी प्रतिभा है। परिवार का सहयोग आपकी शिक्षा में सहायक है।',
  'पंचमेश तीसरे भाव में होने से संचार, लेखन, मीडिया और तकनीकी विषय आपके लिए उपयुक्त हैं। व्यावहारिक अभ्यास से आप कुशल बनते हैं।',
  'पंचमेश चौथे भाव में होने से शांत घर और अच्छे शिक्षक आपकी शिक्षा में सहायक हैं। आप उच्च अध्ययन और शैक्षणिक उपाधियों में अच्छा कर सकते हैं।',
  'पंचमेश अपने ही पाँचवें भाव में होने से बुद्धि और ज्ञान प्रबल हैं। आप प्रतियोगी परीक्षाओं, रचनात्मक क्षेत्रों और परामर्श के विषयों में उत्कृष्टता पा सकते हैं।',
  'पंचमेश छठे भाव में होने से शिक्षा में बाधाएँ आ सकती हैं, पर लगन से जीत मिलती है। चिकित्सा, कानून, सेवा और प्रतियोगी परीक्षाएँ आपके लिए उपयुक्त हैं।',
  'पंचमेश सातवें भाव में होने से आप चर्चा और साझेदारी से अच्छा सीखते हैं। वाणिज्य, कानून, कूटनीति और व्यापार अध्ययन शुभ हैं।',
  'पंचमेश आठवें भाव में होने से पढ़ाई में कभी-कभी रुकावट आ सकती है, पर आपका मन गहन और शोधपरक है। शोध, विज्ञान और गूढ़ विषय आपको आकर्षित करते हैं।',
  'पंचमेश नौवें भाव में होने से उच्च शिक्षा, दर्शन, कानून और विदेश में अध्ययन शुभ हैं। अच्छे शिक्षक आपकी शिक्षा में महत्वपूर्ण भूमिका निभाते हैं।',
  'पंचमेश दसवें भाव में होने से आपकी शिक्षा सीधे आपके करियर को सहारा देती है। प्रबंधन, प्रशासन और व्यावसायिक पाठ्यक्रम आपके लिए उपयुक्त हैं।',
  'पंचमेश ग्यारहवें भाव में होने से आपकी पढ़ाई से लाभ और पहचान मिलती है। सामूहिक अध्ययन, तकनीक और व्यावहारिक विषय सफलता दिला सकते हैं।',
  'पंचमेश बारहवें भाव में होने से आप घर से दूर या विदेश में पढ़ सकते हैं। भाषाएँ, आध्यात्मिक विषय और शांत स्थानों पर शोध आपके लिए उपयुक्त हैं।',
 ],
],
'planet_house' => [
 'Sun' => [
  'पहले भाव में सूर्य आत्मविश्वास, नेतृत्व और प्रबल व्यक्तित्व देता है। आपको सम्मान और अधिकार पसंद है, पर अहंकार और क्रोध पर नियंत्रण रखें। स्वास्थ्य प्रायः अच्छा रहता है, पर आँखों और सिर का ध्यान रखें।',
  'दूसरे भाव में सूर्य धन को सरकार, अधिकार या पारिवारिक प्रतिष्ठा से जोड़ता है। आपकी वाणी दृढ़ और गरिमामय होती है। पारिवारिक संपत्ति पर विवाद से बचें।',
  'तीसरे भाव में सूर्य साहस, पहल और स्वयं के प्रयास से सफलता देता है। संचार, यात्रा और प्रतिस्पर्धी कार्यों में आप अच्छा कर सकते हैं, और भाई-बहन आपका आदर करते हैं।',
  'चौथे भाव में सूर्य घर में अधिकार दे सकता है, पर माता-पिता से कुछ तनाव भी संभव है। संपत्ति जीवन में बाद में मिल सकती है। अधिक नियंत्रण से बचने पर घर में शांति बढ़ती है।',
  'पाँचवें भाव में सूर्य रचनात्मक या शैक्षणिक क्षेत्रों में बुद्धि, महत्वाकांक्षा और नेतृत्व देता है। संतान कम पर योग्य हो सकती है। जोखिम भरे सट्टे से बचें।',
  'छठे भाव में सूर्य शत्रुओं पर विजय और सेवा, स्वास्थ्य या सरकारी कार्य में सफलता देता है। आपकी रोग-प्रतिरोधक क्षमता अच्छी है, पर अधिक तनाव से बचें।',
  'सातवें भाव में सूर्य जीवनसाथी को दृढ़ इच्छाशक्ति वाला और सम्मानित बनाता है। विवाह और व्यापार में अहं के टकराव को धैर्य और आपसी सम्मान से संभालें।',
  'आठवें भाव में सूर्य अचानक परिवर्तन और शोध तथा गूढ़ विषयों में रुचि दे सकता है। आँखों और हृदय के स्वास्थ्य पर ध्यान दें। विरासत से जुड़े मामले उठ सकते हैं।',
  'नौवें भाव में सूर्य भाग्य, सम्मान और धर्म की प्रबल भावना देता है। आप उदारता से दूसरों की सहायता कर सकते हैं। पिता या गुरु से मतभेद संभव हैं, पर आस्था आपका साथ देती है।',
  'दसवें भाव में सूर्य करियर, अधिकार और यश के लिए बहुत प्रबल है। सरकारी नौकरी, प्रशासन और नेतृत्व की भूमिकाएँ आपके लिए उपयुक्त हैं, और समय के साथ प्रतिष्ठा बढ़ती है।',
  'ग्यारहवें भाव में सूर्य प्रभावशाली लोगों और सरकार से लाभ देता है। आपकी आय निरंतर बढ़ती है, और आपके मित्र शक्तिशाली होते हैं।',
  'बारहवें भाव में सूर्य खर्च, विदेशी संबंध और आध्यात्मिक झुकाव दे सकता है। दृष्टि और नींद का ध्यान रखें। दान और सेवा से आपको आंतरिक संतोष मिलता है।',
 ],
 'Moon' => [
  'पहले भाव में चंद्र आपको संवेदनशील, आकर्षक और लोकप्रिय बनाता है। आपकी मनोदशा जल्दी बदलती है, इसलिए भावनात्मक संतुलन महत्वपूर्ण है। आप स्नेही और कल्पनाशील हैं।',
  'दूसरे भाव में चंद्र मधुर वाणी, परिवार से लगाव और स्थिर धन देता है। आपको अच्छा भोजन पसंद है, और सावधान बचत से आर्थिक लाभ होता है।',
  'तीसरे भाव में चंद्र रचनात्मक मन और यात्रा तथा संवाद का प्रेम देता है। आप भाई-बहनों के निकट रहते हैं, पर आपका साहस मनोदशा पर निर्भर हो सकता है।',
  'चौथे भाव में चंद्र बहुत सुखदायक है: यह सुखी घर, माता का प्रेम और संपत्ति देता है। घर की भावनात्मक शांति आपकी सफलता की नींव है।',
  'पाँचवें भाव में चंद्र कल्पनाशीलता, भावनात्मक बुद्धि और संतान से स्नेह देता है। रचनात्मक और शैक्षणिक कार्य आपके लिए उपयुक्त हैं।',
  'छठे भाव में चंद्र आपको आवश्यकता से अधिक चिंता करने वाला बना सकता है। सेवा के कार्यों में आप परिश्रम करते हैं, पर पाचन और भावनात्मक तनाव का ध्यान रखें।',
  'सातवें भाव में चंद्र देखभाल करने वाला, आकर्षक साथी और सार्वजनिक व्यवहार में सफलता देता है। जनता से जुड़ा व्यापार और यात्रा शुभ हैं।',
  'आठवें भाव में चंद्र आपको अंतर्ज्ञानी और रहस्यों में रुचि रखने वाला बनाता है, पर भावनात्मक उतार-चढ़ाव संभव हैं। ध्यान और स्थिर दिनचर्या सहायक है।',
  'नौवें भाव में चंद्र आस्था, यात्रा प्रेम और दानशील स्वभाव देता है। सौभाग्य प्रायः माता या धार्मिक कार्यों से आता है।',
  'दसवें भाव में चंद्र सार्वजनिक लोकप्रियता और ऐसा करियर देता है जो कई बार बदल सकता है। लोगों, यात्रा या तरल पदार्थों से जुड़ा काम उपयुक्त है।',
  'ग्यारहवें भाव में चंद्र लाभ, अनेक मित्र और इच्छा पूर्ति देता है। सामाजिक संपर्कों से आपकी आय बढ़ती है।',
  'बारहवें भाव में चंद्र समृद्ध आंतरिक जीवन, एकांत प्रेम और संभावित विदेशी संबंध देता है। नींद की गुणवत्ता और खर्चों का ध्यान रखें।',
 ],
 'Mars' => [
  'पहले भाव में मंगल आपको साहसी, ऊर्जावान और प्रतिस्पर्धी बनाता है। आप तेज़ी से कार्य करते हैं, इसलिए क्रोध और दुर्घटनाओं से सावधान रहें। यह स्थिति मंगल दोष की जाँच में गिनी जाती है।',
  'दूसरे भाव में मंगल वाणी को तीखा और खर्च को आवेगपूर्ण बना सकता है। संपत्ति, इंजीनियरिंग या तकनीकी काम से आप कमा सकते हैं। परिवार में कठोर शब्दों से बचें।',
  'तीसरे भाव में मंगल अत्यधिक साहस, सहनशक्ति और प्रयास से सफलता देता है। आप प्रतिस्पर्धा और खेल में जीत सकते हैं, और भाई-बहनों की रक्षा करते हैं।',
  'चौथे भाव में मंगल संपत्ति और वाहन दे सकता है, पर घर में कुछ अशांति भी। घरेलू मामलों में धैर्य रखें। यह स्थिति मंगल दोष की जाँच में गिनी जाती है।',
  'पाँचवें भाव में मंगल तीक्ष्ण, प्रतिस्पर्धी बुद्धि देता है। तकनीकी पढ़ाई और खेल में आप अच्छा कर सकते हैं, पर जल्दबाज़ी के निवेश से बचें।',
  'छठे भाव में मंगल प्रबल है: आप शत्रुओं को हराते हैं, प्रतिस्पर्धा संभालते हैं और सेवा, पुलिस, सेना या चिकित्सा क्षेत्र में सफल होते हैं।',
  'सातवें भाव में मंगल ऊर्जावान साथी देता है, पर विवाह में मतभेदों को धैर्य से संभालें। यह स्थिति मंगल दोष की जाँच में गिनी जाती है।',
  'आठवें भाव में मंगल दुर्घटनाओं, शल्यक्रिया और अचानक घटनाओं के प्रति सावधानी माँगता है। आपमें ठीक होने की प्रबल शक्ति है। यह स्थिति मंगल दोष की जाँच में गिनी जाती है।',
  'नौवें भाव में मंगल दृढ़ विश्वास और साहसिक कार्यों तथा यात्रा का प्रेम देता है। बड़ों से बहस संभव है, पर साहस भाग्य लाता है।',
  'दसवें भाव में मंगल करियर के लिए शक्तिशाली है: साहसी कदमों से आप इंजीनियरिंग, रक्षा, खेल, शल्य चिकित्सा या प्रबंधन में ऊपर उठ सकते हैं।',
  'ग्यारहवें भाव में मंगल प्रयास, संपत्ति और प्रभावशाली मित्रों से लाभ देता है। पहल करने पर आपकी आय बढ़ती है।',
  'बारहवें भाव में मंगल छिपे खर्च और बेचैनी दे सकता है। नींद और क्रोध का ध्यान रखें। यह स्थिति मंगल दोष की जाँच में गिनी जाती है।',
 ],
 'Mercury' => [
  'पहले भाव में बुध युवा रूप, तीव्र बुद्धि और अच्छा संवाद कौशल देता है। आप जल्दी सीखते हैं और आसानी से ढल जाते हैं।',
  'दूसरे भाव में बुध चतुर वाणी और धन संभालने का कौशल देता है। व्यापार, लेखा, शिक्षण और बोलने से आय हो सकती है।',
  'तीसरे भाव में बुध लेखन प्रतिभा, तीक्ष्ण सोच और मीडिया, बिक्री तथा छोटी यात्राओं में सफलता देता है।',
  'चौथे भाव में बुध अच्छी शिक्षा और बुद्धिमान घरेलू वातावरण देता है। संपत्ति के लेन-देन से लाभ हो सकता है।',
  'पाँचवें भाव में बुध बुद्धि, हास्य और पढ़ाई, परामर्श तथा रचनात्मक लेखन में सफलता देता है।',
  'छठे भाव में बुध आपको विश्लेषक और समस्याएँ सुलझाने में कुशल बनाता है। सेवा, लेखा और स्वास्थ्य क्षेत्र उपयुक्त हैं; व्यर्थ चिंता से बचें।',
  'सातवें भाव में बुध बुद्धिमान, युवा साथी और व्यापारिक साझेदारी तथा वाणिज्य में सफलता देता है।',
  'आठवें भाव में बुध शोधपरक बुद्धि और गूढ़ विषयों में रुचि देता है। तंत्रिका स्वास्थ्य का ध्यान रखें।',
  'नौवें भाव में बुध दर्शन, भाषाओं और उच्च शिक्षा में रुचि देता है। शिक्षण और प्रकाशन शुभ हैं।',
  'दसवें भाव में बुध व्यापार, संचार, आईटी, लेखा या लेखन के करियर को सहारा देता है। आप अपने काम में चतुर हैं।',
  'ग्यारहवें भाव में बुध व्यापार, संपर्कों और बुद्धि से लाभ देता है। आय के अनेक स्रोत संभव हैं।',
  'बारहवें भाव में बुध आपको विचारशील और निजी स्वभाव का बना सकता है। विदेश व्यापार या पर्दे के पीछे का काम उपयुक्त है; खर्चों पर नियंत्रण रखें।',
 ],
 'Jupiter' => [
  'पहले भाव में गुरु ज्ञान, अच्छा चरित्र और सम्मान देता है। आप आशावादी और सहायक हैं, और सौभाग्य आपकी रक्षा करता है।',
  'दूसरे भाव में गुरु धन, सत्य वाणी और सुसंस्कृत परिवार देता है। शिक्षण, वित्त या परामर्श से आप कमा सकते हैं।',
  'तीसरे भाव में गुरु अच्छे संस्कार और ज्ञान तथा संवाद से सफलता देता है, पर जोखिम लेने के लिए अतिरिक्त साहस चाहिए।',
  'चौथे भाव में गुरु सुखी घर, अच्छी शिक्षा, वाहन और संपत्ति देता है। मानसिक शांति इस स्थिति का आशीर्वाद है।',
  'पाँचवें भाव में गुरु बुद्धि, संतान और शिक्षा के लिए उत्तम है। आप अच्छे शिक्षक या सलाहकार बन सकते हैं।',
  'छठे भाव में गुरु ज्ञान से बाधाओं पर विजय में सहायता करता है, पर वज़न और यकृत के स्वास्थ्य का ध्यान रखें। सेवा कार्य उपयुक्त है।',
  'सातवें भाव में गुरु समझदार, सहयोगी साथी और साझेदारी तथा सार्वजनिक व्यवहार में सफलता देता है।',
  'आठवें भाव में गुरु दीर्घायु, आध्यात्मिकता में रुचि और संभावित विरासत देता है। शोध और गूढ़ ज्ञान आपको आकर्षित करते हैं।',
  'नौवें भाव में गुरु अत्यंत भाग्यशाली है: यह आस्था, उच्च शिक्षा, अच्छे गुरु और पिता का सहयोग देता है।',
  'दसवें भाव में गुरु करियर में सम्मान देता है। शिक्षण, कानून, वित्त, प्रशासन और परामर्श की भूमिकाएँ उपयुक्त हैं।',
  'ग्यारहवें भाव में गुरु बड़ा लाभ, प्रभावशाली मित्र और इच्छा पूर्ति देता है। आय निरंतर बढ़ती है।',
  'बारहवें भाव में गुरु आपको आध्यात्मिक और दानशील बनाता है। शुभ कार्यों और विदेश यात्रा पर खर्च संभव है।',
 ],
 'Venus' => [
  'पहले भाव में शुक्र आकर्षण, सुंदरता और कलात्मक रुचि देता है। आपको सौंदर्य और सुख-सुविधा पसंद है, और लोग आपकी ओर खिंचते हैं।',
  'दूसरे भाव में शुक्र मधुर वाणी, पारिवारिक धन और अच्छे भोजन तथा वस्तुओं का प्रेम देता है।',
  'तीसरे भाव में शुक्र लेखन, संगीत या डिज़ाइन में कलात्मक प्रतिभा और भाई-बहनों से मधुर संबंध देता है।',
  'चौथे भाव में शुक्र सुंदर घर, वाहन और सुख-सुविधाएँ देता है। आपकी माता स्नेही और सुसंस्कृत हो सकती हैं।',
  'पाँचवें भाव में शुक्र रचनात्मकता, प्रेम और कला, मनोरंजन या शिक्षा में सफलता देता है।',
  'छठे भाव में शुक्र भोग-विलास से छोटी स्वास्थ्य समस्याएँ और संबंधों में कुछ कठिनाइयाँ दे सकता है। सौंदर्य, स्वास्थ्य या आतिथ्य सेवा उपयुक्त है।',
  'सातवें भाव में शुक्र आकर्षक, प्रेमी साथी और व्यापारिक साझेदारी में सफलता देता है।',
  'आठवें भाव में शुक्र जीवनसाथी या विरासत से लाभ और गूढ़ विषयों में रुचि दे सकता है। सुखों में संतुलन की सलाह है।',
  'नौवें भाव में शुक्र कला, यात्रा और सुसंस्कृत दृष्टिकोण से भाग्य देता है। आपका साथी भाग्य ला सकता है।',
  'दसवें भाव में शुक्र कला, फ़ैशन, मीडिया, आतिथ्य, वित्त या सौंदर्य के करियर को सहारा देता है। कार्यस्थल पर लोग आपको पसंद करते हैं।',
  'ग्यारहवें भाव में शुक्र लाभ, सुख-सुविधाएँ और अनेक मित्र देता है। कला, विलासिता की वस्तुओं या महिलाओं से जुड़े व्यापार से आय संभव है।',
  'बारहवें भाव में शुक्र सुख, यात्रा और निजी आनंद का प्रेम देता है। विलासिता पर खर्च की योजना बनाएँ।',
 ],
 'Saturn' => [
  'पहले भाव में शनि आपको गंभीर, अनुशासित और परिश्रमी बनाता है। आरंभिक जीवन कठिन हो सकता है, पर उम्र के साथ सफलता निरंतर बढ़ती है।',
  'दूसरे भाव में शनि आरंभ में बचत धीमी और वाणी सावधान या रूखी बना सकता है। अनुशासन से समय के साथ धन बनता है।',
  'तीसरे भाव में शनि अत्यधिक लगन और साहस देता है। लंबे, धैर्यपूर्ण प्रयास से आप सफल होते हैं।',
  'चौथे भाव में शनि घरेलू सुख या संपत्ति में देरी कर सकता है। धैर्य और माता की सेवा से घर में स्थिरता आती है।',
  'पाँचवें भाव में शनि शिक्षा या संतान के परिणामों में देरी कर सकता है, पर गंभीर, व्यावहारिक बुद्धि देता है।',
  'छठे भाव में शनि शत्रुओं को हराने, सेवा कार्य संभालने और अनुशासन से रोगों पर विजय के लिए प्रबल है।',
  'सातवें भाव में शनि विवाह में देरी या परिपक्व, ज़िम्मेदार साथी दे सकता है। साझेदारी में धैर्य और निष्ठा चाहिए।',
  'आठवें भाव में शनि दीर्घायु देता है, पर लंबी स्वास्थ्य समस्याएँ या देरी ला सकता है। शोध और धैर्य आपके लिए लाभदायक हैं।',
  'नौवें भाव में शनि आस्था के प्रति व्यावहारिक, अनुशासित दृष्टिकोण देता है। भाग्य धीरे पर निरंतर परिश्रम से आता है।',
  'दसवें भाव में शनि कठिन परिश्रम पर बने लंबे, स्थिर करियर के लिए शक्तिशाली है, प्रायः प्रशासन, कानून, उद्योग या जनसेवा में।',
  'ग्यारहवें भाव में शनि विशेषकर जीवन के उत्तरार्ध में स्थिर, दीर्घकालिक लाभ देता है। आपके कुछ भरोसेमंद मित्र होते हैं।',
  'बारहवें भाव में शनि खर्च, एकांत या विदेश में काम दे सकता है। ध्यान, सेवा और दान से शांति मिलती है।',
 ],
 'Rahu' => [
  'पहले भाव में राहु महत्वाकांक्षा और अव्यक्तित्व देता है। आप बेचैन या गलत समझे जाने का अनुभव कर सकते हैं, इसलिए लक्ष्यों की स्पष्टता महत्वपूर्ण है।',
  'दूसरे भाव में राहु वाणी और आर्थिक स्थिति को अप्रत्याशित बना सकता है। विदेशी या असामान्य स्रोतों से आय संभव है; कठोर शब्दों से बचें।',
  'तीसरे भाव में राहु साहस और मीडिया, तकनीक तथा साहसी उद्यमों में सफलता देता है। प्रयास के लिए यह शुभ स्थिति है।',
  'चौथे भाव में राहु घर में बेचैनी या बार-बार निवास परिवर्तन दे सकता है। मानसिक शांति के लिए प्रयास चाहिए।',
  'पाँचवें भाव में राहु असामान्य बुद्धि और सट्टा, तकनीक या विदेशी शिक्षा में रुचि देता है। जोखिम भरे निवेश से बचें।',
  'छठे भाव में राहु शत्रुओं को हराने और प्रतिस्पर्धा में सफलता में सहायता करता है। इसके अनुसार यह शुभ स्थिति है।',
  'सातवें भाव में राहु अया विदेशी साथी दे सकता है। साझेदारी में स्पष्ट संवाद और विश्वास चाहिए।',
  'आठवें भाव में राहु अचानक घटनाएँ और गूढ़ विषयों में रुचि दे सकता है। स्वास्थ्य और धन के प्रति सावधानी की सलाह है।',
  'नौवें भाव में राहु आपको परंपरा पर प्रश्न करने और अपना मार्ग खोजने वाला बना सकता है। विदेश यात्रा और असामान्य गुरु प्रभावित कर सकते हैं।',
  'दसवें भाव में राहु प्रबल महत्वाकांक्षा और तकनीक, राजनीति, मीडिया या विदेश से जुड़े काम में सफलता देता है।',
  'ग्यारहवें भाव में राहु बड़ा लाभ, विस्तृत नेटवर्क और महत्वाकांक्षाओं की पूर्ति देता है। यह शुभ स्थिति है।',
  'बारहवें भाव में राहु विदेश में बसना, छिपे खर्च या नींद की समस्याएँ दे सकता है। आध्यात्मिक साधना से शांति मिलती है।',
 ],
 'Ketu' => [
  'पहले भाव में केतु अंतर्ज्ञानी, आध्यात्मिक स्वभाव देता है, पर कभी-कभी आप अपनी पहचान को लेकर अनिश्चित हो सकते हैं। ध्यान सहायक है।',
  'दूसरे भाव में केतु धन या पारिवारिक मामलों से विरक्ति दे सकता है। सावधान वाणी और बचत की सलाह है।',
  'तीसरे भाव में केतु साहस और अंतर्ज्ञान तथा साहसी या आध्यात्मिक कार्यों में सफलता देता है।',
  'चौथे भाव में केतु घर से लगाव कम कर सकता है और निवास में परिवर्तन ला सकता है। आंतरिक शांति आध्यात्मिकता से आती है।',
  'पाँचवें भाव में केतु गहन, अंतर्ज्ञानी बुद्धि और आध्यात्मिक अध्ययन में रुचि देता है। सट्टे में सावधानी रखें।',
  'छठे भाव में केतु शत्रुओं और रोगों पर विजय में सहायता करता है। इसके अनुसार यह शुभ स्थिति है।',
  'सातवें भाव में केतु साझेदारी में विरक्ति या गलतफ़हमी दे सकता है। धैर्य और खुलापन संबंधों में सहायक है।',
  'आठवें भाव में केतु प्रबल अंतर्ज्ञान और रहस्यवाद तथा शोध में रुचि देता है। स्वास्थ्य की नियमित देखभाल आवश्यक है।',
  'नौवें भाव में केतु धर्म के प्रति आध्यात्मिक, स्वतंत्र दृष्टिकोण देता है। आप अपने ढंग से ज्ञान खोज सकते हैं।',
  'दसवें भाव में केतु करियर में परिवर्तन या पद-प्रतिष्ठा से विरक्ति का भाव दे सकता है। सेवा-प्रधान काम उपयुक्त है।',
  'ग्यारहवें भाव में केतु अप्रत्याशित लाभ और कुछ घनिष्ठ मित्र देता है। इच्छाओं के पीछे अधिक न भागने पर वे पूरी होती हैं।',
  'बारहवें भाव में केतु इसके अनुसार आध्यात्मिकता और मोक्ष के लिए शुभ है। ध्यान, एकांतवास और दान आपके लिए उपयुक्त हैं।',
 ],
],
'remedies' => [
 'Sun' => ['प्रतिदिन सुबह उगते सूर्य को जल अर्पित करें।', 'पिता और बड़ों का सम्मान करें, और अहं के टकराव से बचें।', 'रविवार को गेहूँ या गुड़ का दान करें।'],
 'Moon' => ['माता का सम्मान करें और नियमित रूप से उनका आशीर्वाद लें।', 'चाँदी की कोई छोटी वस्तु अपने पास रखें या चाँदी धारण करें।', 'सोमवार को चावल, दूध या सफ़ेद वस्त्र का दान करें।'],
 'Mars' => ['मंगलवार को हनुमान चालीसा का पाठ करें।', 'क्रोध पर नियंत्रण रखें और भाइयों से झगड़े से बचें।', 'मंगलवार को मसूर दाल का दान करें।'],
 'Mercury' => ['बुधवार को गाय को हरी घास खिलाएँ।', 'अपनी वाणी कोमल और सत्य रखें।', 'बुधवार को हरी मूंग दाल या हरी सब्ज़ियों का दान करें।'],
 'Jupiter' => ['गुरुजनों और बड़ों का सम्मान करें और उनका मार्गदर्शन लें।', 'माथे पर केसर या हल्दी का तिलक लगाएँ।', 'गुरुवार को चने की दाल या हल्दी जैसी पीली वस्तुओं का दान करें।'],
 'Venus' => ['स्वयं को और अपने घर को स्वच्छ तथा सुगंधित रखें।', 'महिलाओं का सम्मान करें और संबंधों में अच्छा आचरण रखें।', 'शुक्रवार को सफ़ेद मिठाई, दही या चावल का दान करें।'],
 'Saturn' => ['वृद्ध और गरीब लोगों की सेवा करें, और कर्मचारियों से उचित व्यवहार करें।', 'शनिवार को पीपल के नीचे सरसों के तेल का दीपक जलाएँ।', 'शराब और मांसाहार से बचें, विशेषकर शनिवार को।'],
 'Rahu' => ['मन को शांत रखें और धोखे वाले व्यवहार से बचें।', 'शनिवार को पक्षियों को दाना डालें या ज़रूरतमंदों को दान करें।', 'शनिवार को “ॐ राहवे नमः” का 108 बार जप करें।'],
 'Ketu' => ['कुत्तों को भोजन दें या उनकी देखभाल करें।', 'ज़रूरतमंदों को कंबल या तिल का दान करें।', 'मंगलवार को “ॐ केतवे नमः” का 108 बार जप करें।'],
],
];
